cypress_script:
describe('User Avatars Profile Links', () => {
  it('should display the profile link on hover for User 1', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('.figure').first().trigger('mouseover');
    cy.get('a').contains('View profile').should('be.visible');
    cy.get('a').contains('View profile').click();
    cy.url().should('include', '/users/1');
  });

  it('should not navigate to a profile if the avatar is not hovered', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('.figure').first().should('be.visible');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars Profile Links', () => {
  test('should display the profile link on hover for User 1', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const user1Avatar = page.locator('.figure').nth(0);
    await user1Avatar.hover();
    const profileLink = page.locator('a').filter({ hasText: 'View profile' });
    await expect(profileLink).toBeVisible();
    await profileLink.click();
    await expect(page).toHaveURL(/.*\/users\/1/);
  });

  test('should not navigate to a profile if the avatar is not hovered', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const user1Avatar = page.locator('.figure').nth(0);
    await expect(user1Avatar).toBeVisible();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/hovers');
  });
});
